//! Restricted adapter for an independently running, loopback Freefield server.
//! Freefield is not bundled. Never repeat an uncertain POST automatically.
use super::{error,AppState};
use axum::{body::{Body,Bytes},extract::{Multipart,State},http::{header,StatusCode},response::{IntoResponse,Response},Json};
use reqwest::{Client,Url};
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs::{self,OpenOptions},io::{Read,Write},path::{Path,PathBuf},time::Duration};
const JSON_LIMIT:usize=4*1024*1024;
const UPLOAD_LIMIT:usize=100*1024*1024;
const MEDIA_LIMIT:usize=64*1024*1024;

pub struct Hub {root:Result<PathBuf,String>}
impl Default for Hub {fn default()->Self{Self{root:std::env::var_os("HOME").map(PathBuf::from).map(|p|p.join("Library/Application Support/Frame/Companion/freefield-ledger")).ok_or("Cannot find a private Freefield request ledger".into())}}}
impl Hub {#[cfg(test)] fn at(path:PathBuf)->Self{Self{root:Ok(path)}}}
#[derive(Deserialize)] #[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Request {server_url:String,#[serde(default)] request_id:Option<String>,#[serde(default)] app_id:Option<String>,#[serde(default)] preset:Option<String>,#[serde(default)] remote_id:Option<String>,#[serde(default)] approved:Option<bool>,#[serde(default)] values:BTreeMap<String,Value>,#[serde(default)] index:Option<usize>}
struct Upload {field:String,filename:String,mime:String,data:Bytes}
#[derive(Serialize,Deserialize)] #[serde(rename_all="camelCase",deny_unknown_fields)]
struct Record {version:u8,request_id:String,server_digest:String,app_id:String,arguments_digest:String,status:String,#[serde(skip_serializing_if="Option::is_none")]remote_id:Option<String>}
fn hash(value:&[u8])->String{format!("{:x}",Sha256::digest(value))}
fn endpoint(value:&str)->Result<Url,String>{let mut u=Url::parse(value).map_err(|_|"Invalid Freefield address")?;if u.scheme()!="http"||!matches!(u.host_str(),Some("127.0.0.1"|"localhost"|"[::1]"))||u.port().is_none_or(|p|p<1024||p==4319)||!u.username().is_empty()||u.password().is_some()||u.query().is_some()||u.fragment().is_some()||u.path()!="/"{return Err("Use an HTTP loopback Freefield address with an explicit port and no path or credentials.".into())}if u.host_str()==Some("localhost"){u.set_host(Some("127.0.0.1")).map_err(|_|"Invalid Freefield address")?}Ok(u)}
fn client()->Result<Client,String>{Client::builder().no_proxy().redirect(reqwest::redirect::Policy::none()).connect_timeout(Duration::from_secs(5)).timeout(Duration::from_secs(45)).build().map_err(|_|"Could not create local Freefield client".into())}
fn key(v:&str)->bool{!v.is_empty()&&v.len()<=100&&v.bytes().all(|c|c.is_ascii_alphanumeric()||matches!(c,b'_'|b'-'))}
fn app_id(v:&str)->bool{!v.is_empty()&&v.len()<=80&&!v.starts_with('-')&&!v.ends_with('-')&&v.bytes().all(|c|c.is_ascii_lowercase()||c.is_ascii_digit()||c==b'-')}
fn remote_id(v:&str)->bool{let b=v.as_bytes();b.len()==23&&b.get(8)==Some(&b'-')&&b.get(18)==Some(&b'-')&&b.iter().enumerate().all(|(i,c)|if i==8||i==18{*c==b'-'}else if i>=19{c.is_ascii_digit()||matches!(*c,b'a'..=b'f')}else{c.is_ascii_digit()})}
fn canonical_uuid(v:&str)->bool{uuid::Uuid::parse_str(v).is_ok_and(|u|u.to_string()==v)}
fn media_type(data:&[u8])->Option<(&'static str,&'static str)>{if data.starts_with(b"\x89PNG\r\n\x1a\n"){Some(("image/png","image"))}else if data.starts_with(&[0xff,0xd8,0xff]){Some(("image/jpeg","image"))}else if data.starts_with(b"GIF87a")||data.starts_with(b"GIF89a"){Some(("image/gif","image"))}else if data.starts_with(b"RIFF")&&data.get(8..12)==Some(b"WEBP"){Some(("image/webp","image"))}else if data.starts_with(b"RIFF")&&data.get(8..12)==Some(b"WAVE"){Some(("audio/wav","audio"))}else if data.starts_with(b"ID3")||data.len()>2&&data[0]==0xff&&(data[1]&0xe0)==0xe0{Some(("audio/mpeg","audio"))}else if data.starts_with(b"fLaC"){Some(("audio/flac","audio"))}else if data.starts_with(b"OggS"){Some(("audio/ogg","audio"))}else if data.get(4..8)==Some(b"ftyp"){Some(("video/mp4","video"))}else if data.starts_with(&[0x1a,0x45,0xdf,0xa3]){Some(("video/webm","video"))}else{None}}
fn input_mime(detected:&str,declared:&str)->Option<&'static str>{match(detected,declared){("image/png","image/png")=>Some("image/png"),("image/jpeg","image/jpeg")=>Some("image/jpeg"),("image/gif","image/gif")=>Some("image/gif"),("image/webp","image/webp")=>Some("image/webp"),("audio/wav","audio/wav"|"audio/x-wav"|"audio/wave")=>Some("audio/wav"),("audio/mpeg","audio/mpeg")=>Some("audio/mpeg"),("audio/flac","audio/flac")=>Some("audio/flac"),("audio/ogg","audio/ogg")=>Some("audio/ogg"),("video/mp4","video/mp4")=>Some("video/mp4"),("video/mp4","video/quicktime")=>Some("video/quicktime"),("video/mp4","audio/mp4")=>Some("audio/mp4"),("video/webm","video/webm")=>Some("video/webm"),("video/webm","audio/webm")=>Some("audio/webm"),_=>None}}
fn output_mime(detected:&str,kind:&str)->Option<&'static str>{match(detected,kind){("video/mp4","audio")=>Some("audio/mp4"),("video/webm","audio")=>Some("audio/webm"),("image/gif","video")=>Some("image/gif"),("video/mp4","video")=>Some("video/mp4"),("video/webm","video")=>Some("video/webm"),("image/png","image")=>Some("image/png"),("image/jpeg","image")=>Some("image/jpeg"),("image/webp","image")=>Some("image/webp"),("image/gif","image")=>Some("image/gif"),("audio/wav","audio")=>Some("audio/wav"),("audio/mpeg","audio")=>Some("audio/mpeg"),("audio/flac","audio")=>Some("audio/flac"),("audio/ogg","audio")=>Some("audio/ogg"),_=>None}}
fn secret_field(name:&str)->bool{let n=name.to_ascii_lowercase().replace(['_','-'],"");["apikey","accesstoken","authorization","password","secret","bearertoken"].iter().any(|word|n==*word||n.ends_with(word))}
fn multipart(request:&Request,uploads:&[Upload])->Result<(Vec<u8>,String),String>{
 if request.values.len()>64||uploads.len()>8{return Err("Too many Freefield inputs".into())}
 let boundary=format!("frame-{}",uuid::Uuid::new_v4().simple());let capacity=uploads.iter().map(|u|u.data.len()).sum::<usize>()+request.values.iter().map(|(k,v)|k.len()+v.to_string().len()).sum::<usize>()+16384;let mut body=Vec::with_capacity(capacity.min(UPLOAD_LIMIT+1024*1024));let mut names=std::collections::HashSet::new();
 for(k,v)in &request.values{if !key(k)||secret_field(k)||!names.insert(k.clone()){return Err("Invalid input name or credential field".into())}let text=match v{Value::String(s)=>s.clone(),Value::Number(n)=>n.to_string(),Value::Bool(b)=>b.to_string(),Value::Array(a) if a.len()<=200&&a.iter().all(|v|v.is_string()||v.is_number()||v.is_boolean())=>v.to_string(),_=>return Err("Freefield inputs must be text, numbers, booleans, or selection lists".into())};if text.len()>65536{return Err("An input is too large".into())}write!(&mut body,"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{text}\r\n").map_err(|_|"Could not build inputs")?;}
 if let Some(preset)=request.preset.as_deref(){if !app_id(preset)||!names.insert("preset".into()){return Err("Invalid or duplicate Freefield preset".into())}write!(&mut body,"--{boundary}\r\nContent-Disposition: form-data; name=\"preset\"\r\n\r\n{preset}\r\n").map_err(|_|"Could not build inputs")?;}
 let mut total=0;for upload in uploads{if !key(&upload.field)||secret_field(&upload.field)||!names.insert(upload.field.clone())||upload.filename.is_empty()||upload.filename.len()>100||!upload.filename.bytes().all(|v|v.is_ascii_alphanumeric()||matches!(v,b'.'|b'_'|b'-'|b' ')){return Err("Invalid reference upload name".into())}let data=&upload.data;total+=data.len();if total>UPLOAD_LIMIT{return Err("Reference uploads exceed 100 MiB together".into())}let(detected,_)=media_type(data).ok_or("Reference is not a supported media file")?;let mime=input_mime(detected,&upload.mime).ok_or("Reference media bytes do not match the selected type")?;write!(&mut body,"--{boundary}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\nContent-Type: {}\r\n\r\n",upload.field,upload.filename,mime).map_err(|_|"Could not build inputs")?;body.extend_from_slice(data);body.extend_from_slice(b"\r\n");}
 write!(&mut body,"--{boundary}--\r\n").map_err(|_|"Could not build inputs")?;if body.len()>UPLOAD_LIMIT+1024*1024{return Err("Inputs exceed the request limit".into())}Ok((body,boundary))
}
fn ensure(root:&Path)->Result<(),String>{fs::create_dir_all(root).map_err(|_|"Cannot open the private Freefield ledger")?;let m=fs::symlink_metadata(root).map_err(|_|"Cannot inspect the Freefield ledger")?;if !m.is_dir()||m.file_type().is_symlink(){return Err("Freefield ledger must be a real private directory".into())}#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;fs::set_permissions(root,fs::Permissions::from_mode(0o700)).map_err(|_|"Cannot protect the Freefield ledger")?}Ok(())}
fn sync_dir(root:&Path)->Result<(),String>{fs::File::open(root).and_then(|f|f.sync_all()).map_err(|_|"Could not sync the Freefield ledger; do not resubmit".into())}
fn record_path(root:&Path,id:&str)->PathBuf{root.join(format!("{}.json",hash(id.as_bytes())))}
fn claim(root:&Path,record:&Record)->Result<(),String>{ensure(root)?;if fs::read_dir(root).map_err(|_|"Cannot inspect the Freefield ledger")?.take(10001).count()>=10000{return Err("Freefield ledger limit reached; keep existing receipts and check history before continuing".into())}let path=record_path(root,&record.request_id);let mut opts=OpenOptions::new();opts.write(true).create_new(true);#[cfg(unix)]{use std::os::unix::fs::OpenOptionsExt;opts.mode(0o600);}let mut f=opts.open(path).map_err(|e|if e.kind()==std::io::ErrorKind::AlreadyExists{"This Freefield request was already attempted; check its saved receipt. It will not be resubmitted."}else{"Cannot save the Freefield request before submission."})?;f.write_all(&serde_json::to_vec(record).map_err(|_|"Invalid ledger record")?).and_then(|_|f.sync_all()).map_err(|_|"Could not save the Freefield request; do not resubmit")?;sync_dir(root)}
fn read_record(root:&Path,id:&str)->Result<Record,String>{if !canonical_uuid(id){return Err("Use a saved request UUID".into())}ensure(root)?;let p=record_path(root,id);let m=fs::symlink_metadata(&p).map_err(|_|"No saved Freefield request was found")?;if !m.is_file()||m.file_type().is_symlink()||m.len()>8192{return Err("Saved Freefield receipt is damaged; do not resubmit".into())}let mut data=Vec::new();fs::File::open(p).and_then(|f|f.take(8193).read_to_end(&mut data)).map_err(|_|"Could not read Freefield receipt")?;let r:Record=serde_json::from_slice(&data).map_err(|_|"Saved Freefield receipt is damaged; do not resubmit")?;if r.version!=1||r.request_id!=id||!matches!(r.status.as_str(),"unknown"|"submitted")||r.remote_id.as_deref().is_some_and(|v|!remote_id(v)){return Err("Saved Freefield receipt is damaged; do not resubmit".into())}Ok(r)}
fn save_submitted(root:&Path,record:&Record)->Result<(),String>{let tmp=root.join(format!(".tmp-{}",uuid::Uuid::new_v4()));let mut opts=OpenOptions::new();opts.write(true).create_new(true);#[cfg(unix)]{use std::os::unix::fs::OpenOptionsExt;opts.mode(0o600);}let mut f=opts.open(&tmp).map_err(|_|"Could not save the Freefield run ID; check Freefield history and do not resubmit")?;let result=(||->Result<(),String>{f.write_all(&serde_json::to_vec(record).map_err(|_|"Invalid receipt")?).and_then(|_|f.sync_all()).map_err(|_|"Could not save the Freefield run ID; do not resubmit")?;fs::rename(&tmp,record_path(root,&record.request_id)).map_err(|_|"Could not save the Freefield run ID; do not resubmit")?;sync_dir(root)})();if result.is_err(){let _=fs::remove_file(tmp);}result}
async fn bytes(mut r:reqwest::Response,max:usize)->Result<Vec<u8>,String>{if !r.status().is_success(){return Err(format!("Freefield returned HTTP {}.",r.status().as_u16()))}if r.content_length().is_some_and(|n|n>max as u64){return Err("Freefield response exceeds the size limit".into())}let mut data=Vec::new();while let Some(part)=r.chunk().await.map_err(|_|"Freefield response was interrupted")?{if data.len()+part.len()>max{return Err("Freefield response exceeds the size limit".into())}data.extend_from_slice(&part)}Ok(data)}
async fn get_json(c:&Client,url:Url)->Result<Value,String>{let r=c.get(url).send().await.map_err(|_|"Could not reach local Freefield")?;serde_json::from_slice(&bytes(r,JSON_LIMIT).await?).map_err(|_|"Freefield returned invalid JSON".into())}
fn response(value:Result<Value,String>)->Response{match value{Ok(v)=>Json(v).into_response(),Err(e)=>error(StatusCode::BAD_REQUEST,&e)}}
fn history_id(request:&Request)->Result<&str,String>{request.remote_id.as_deref().filter(|s|remote_id(s)).ok_or("A valid saved Freefield run ID is required".into())}
fn clipped(value:&Value,max:usize)->String{value.as_str().unwrap_or("").chars().take(max).collect()}
fn sanitized_apps(data:&Value)->Result<Value,String>{
 let apps=data["apps"].as_array().ok_or("This service did not identify itself as Freefield")?;if apps.len()>500{return Err("Freefield catalog is too large".into())}let mut result=Vec::new();
 for a in apps{let Some(id)=a["id"].as_str().filter(|v|app_id(v))else{continue};let name=clipped(&a["name"],80);if name.is_empty(){continue}let Some(section)=a["section"].as_str().filter(|v|matches!(*v,"image"|"video"|"audio"|"utility"))else{continue};let Some(status)=a["status"].as_str().filter(|v|matches!(*v,"ready"|"draft"))else{continue};
  let mut inputs=Vec::new();for i in a["inputs"].as_array().into_iter().flatten().take(80){let Some(input_id)=i["id"].as_str().filter(|v|key(v))else{continue};let Some(kind)=i["type"].as_str().filter(|v|matches!(*v,"text"|"textarea"|"number"|"slider"|"select"|"toggle"|"seed"|"image"|"video"|"audio"))else{continue};let label=clipped(&i["label"],120);if label.is_empty(){continue}let mut safe=json!({"id":input_id,"type":kind,"label":label,"required":i["required"]==true});
   for field in ["help","default","min","max","step","multiple","limits"]{if let Some(v)=i.get(field){if v.to_string().len()<=8192{safe[field]=v.clone()}}}
   if let Some(options)=i["options"].as_array(){let options:Vec<_>=options.iter().take(200).filter_map(|o|{let value=o.get("value")?;if !(value.is_string()||value.is_boolean()||value.is_number())||value.to_string().len()>500{return None}let label=clipped(&o["label"],160);if label.is_empty(){return None}Some(json!({"value":value,"label":label}))}).collect();safe["options"]=json!(options)}inputs.push(safe);
  }
  let output:Vec<_>=a["outputs"].as_array().into_iter().flatten().take(30).filter_map(|o|{let t=o["type"].as_str().filter(|v|matches!(*v,"image"|"video"|"audio"))?;Some(json!({"type":t,"label":clipped(&o["label"],120)}))}).collect();
  let presets:Vec<_>=a["presets"].as_array().into_iter().flatten().take(100).filter_map(|v|{let id=v["id"].as_str().filter(|v|app_id(v))?;let label=clipped(&v["label"],120);if label.is_empty(){return None}Some(json!({"id":id,"label":label}))}).collect();
  let models:Vec<_>=a["models"].as_array().into_iter().flatten().take(100).map(|m|json!({"name":clipped(&m["name"],240),"license":clipped(&m["license"],240),"gated":m["gated"]==true,"optional":m["optional"]==true,"gb":m["gb"]})).collect();
  let credits:Vec<_>=a["credits"].as_array().into_iter().flatten().take(50).filter_map(|v|v.as_str().map(|t|t.chars().take(500).collect::<String>())).collect();
  result.push(json!({"id":id,"name":name,"section":section,"summary":clipped(&a["summary"],500),"status":status,"runnable":a["runnable"]==true,"inputs":inputs,"outputs":output,"presets":presets,"models":models,"credits":credits}));
 }Ok(json!({"apps":result}))
}
fn outputs(data:&Value)->Vec<Value>{let mut out=Vec::new();for v in data["outputs"].as_array().into_iter().flatten().take(1000){let Some(name)=v["file"].as_str().filter(|n|safe_output(n))else{continue};let Some(kind)=v["type"].as_str().filter(|s|matches!(*s,"image"|"video"|"audio"))else{continue};out.push(json!({"index":out.len(),"name":name,"kind":kind}));}out}
fn safe_output(name:&str)->bool{let Some((base,ext))=name.rsplit_once('.')else{return false};base.starts_with("out-")&&base.len()<=100&&base.bytes().all(|v|v.is_ascii_lowercase()||v.is_ascii_digit()||matches!(v,b'-'|b'_'))&&!ext.is_empty()&&ext.len()<=5&&ext.bytes().all(|v|v.is_ascii_lowercase()||v.is_ascii_digit())}
async fn history(c:&Client,base:&Url,id:&str)->Result<Value,String>{let data=get_json(c,base.join(&format!("api/history/{id}")).map_err(|_|"Invalid history path")?).await?;if data["id"]!=id{return Err("Freefield returned the wrong run ID".into())}Ok(data)}
pub async fn discover(Json(r):Json<Request>)->Response{response(async{let base=endpoint(&r.server_url)?;sanitized_apps(&get_json(&client()?,base.join("api/apps").unwrap()).await?)}.await)}
async fn read_submission(mut form:Multipart)->Result<(Request,Vec<Upload>),String>{
 let mut metadata:Option<Request>=None;let mut uploads=Vec::new();let mut total=0usize;
 while let Some(field)=form.next_field().await.map_err(|_|"Invalid or oversized Freefield form")?{
  let name=field.name().ok_or("Freefield form field needs a name")?.to_string();
  if name=="metadata"{if metadata.is_some(){return Err("Duplicate Freefield metadata".into())}let data=field.bytes().await.map_err(|_|"Invalid or oversized Freefield metadata")?;if data.len()>65536{return Err("Freefield metadata exceeds 64 KiB".into())}metadata=Some(serde_json::from_slice(&data).map_err(|_|"Invalid Freefield metadata")?);continue}
  if !key(&name)||uploads.len()>=8{return Err("Invalid or excessive reference uploads".into())}let filename=field.file_name().ok_or("Reference upload needs a filename")?.chars().map(|c|if c.is_ascii_alphanumeric()||matches!(c,'.'|'_'|'-'|' '){c}else{'_'}).take(100).collect::<String>();let mime=field.content_type().unwrap_or("").to_string();let data=field.bytes().await.map_err(|_|"Invalid or oversized reference upload")?;total=total.checked_add(data.len()).ok_or("Reference upload is too large")?;if total>UPLOAD_LIMIT{return Err("Reference uploads exceed 100 MiB together".into())}uploads.push(Upload{field:name,filename,mime,data});
 }
 Ok((metadata.ok_or("Freefield metadata is missing")?,uploads))
}
pub async fn submit(State(state):State<AppState>,form:Multipart)->Response{response(async{let(r,uploads)=read_submission(form).await?;let base=endpoint(&r.server_url)?;if r.approved!=Some(true){return Err("Review the Freefield inputs before submitting".into())}let id=r.request_id.as_deref().filter(|s|canonical_uuid(s)).ok_or("A saved request UUID is required")?;let app=r.app_id.as_deref().filter(|s|app_id(s)).ok_or("Choose a valid Freefield app")?;let(body,boundary)=multipart(&r,&uploads)?;let root=state.freefield.root.as_ref().map_err(Clone::clone)?;let mut record=Record{version:1,request_id:id.into(),server_digest:hash(base.as_str().as_bytes()),app_id:app.into(),arguments_digest:hash(&body),status:"unknown".into(),remote_id:None};claim(root,&record)?;
 let res=client()?.post(base.join(&format!("api/apps/{app}/run")).unwrap()).header(header::CONTENT_TYPE,format!("multipart/form-data; boundary={boundary}")).body(body).send().await.map_err(|_|"Submission outcome is unknown. Check Freefield history; this request will not be repeated.")?;
 let data=bytes(res,JSON_LIMIT).await.map_err(|_|"Submission outcome is unknown. Check Freefield history; this request will not be repeated.")?;let v:Value=serde_json::from_slice(&data).map_err(|_|"Submission outcome is unknown. Check Freefield history; this request will not be repeated.")?;let remote=v["id"].as_str().filter(|s|remote_id(s)).ok_or("Submission outcome is unknown. Check Freefield history; this request will not be repeated.")?;record.status="submitted".into();record.remote_id=Some(remote.into());save_submitted(root,&record)?;Ok(json!({"requestId":id,"remoteId":remote,"status":"submitted"}))}.await)}
pub async fn receipt(State(state):State<AppState>,Json(r):Json<Request>)->Response{response(async{let base=endpoint(&r.server_url)?;let id=r.request_id.as_deref().ok_or("A saved request UUID is required")?;let root=state.freefield.root.as_ref().map_err(Clone::clone)?;let record=read_record(root,id)?;if record.server_digest!=hash(base.as_str().as_bytes()){return Err("This request belongs to a different Freefield server".into())}Ok(json!({"requestId":id,"status":record.status,"remoteId":record.remote_id}))}.await)}
pub async fn poll(Json(r):Json<Request>)->Response{response(async{let base=endpoint(&r.server_url)?;let id=history_id(&r)?;let v=history(&client()?,&base,id).await?;let status=v["status"].as_str().filter(|s|matches!(*s,"starting"|"queued"|"running"|"succeeded"|"failed"|"canceled"|"expired"|"lost")).unwrap_or("unknown");Ok(json!({"remoteId":id,"status":status,"outputs":outputs(&v),"progress":v["progress"]}))}.await)}
pub async fn cancel(Json(r):Json<Request>)->Response{response(async{let base=endpoint(&r.server_url)?;if r.approved!=Some(true){return Err("Confirm cancellation before stopping this run".into())}let id=history_id(&r)?;let c=client()?;let res=c.post(base.join(&format!("api/history/{id}/cancel")).unwrap()).send().await.map_err(|_|"Cancellation outcome is unknown; check Freefield history")?;let v:Value=serde_json::from_slice(&bytes(res,JSON_LIMIT).await?).map_err(|_|"Cancellation outcome is unknown; check Freefield history")?;Ok(json!({"remoteId":id,"canceled":v["canceled"]==true}))}.await)}
pub async fn download(Json(r):Json<Request>)->Response{let result:Result<(Vec<u8>,&str),String>=async{let base=endpoint(&r.server_url)?;let id=history_id(&r)?;let index=r.index.filter(|n|*n<1000).ok_or("Select a Freefield output")?;let c=client()?;let listed=outputs(&history(&c,&base,id).await?);let item=listed.get(index).ok_or("This output is not in the saved run history")?;let name=item["name"].as_str().ok_or("Invalid output")?;let res=c.get(base.join(&format!("api/history/{id}/files/{name}")).unwrap()).send().await.map_err(|_|"Could not download Freefield output")?;let data=bytes(res,MEDIA_LIMIT).await?;let(detected,_)=media_type(&data).ok_or("Freefield output is not supported media")?;let mime=output_mime(detected,item["kind"].as_str().unwrap_or("")).ok_or("Freefield output bytes do not match their media kind")?;Ok((data,mime))}.await;match result{Ok((data,mime))=>Response::builder().header(header::CONTENT_TYPE,mime).header(header::CACHE_CONTROL,"no-store").header(header::X_CONTENT_TYPE_OPTIONS,"nosniff").body(Body::from(data)).unwrap(),Err(e)=>error(StatusCode::BAD_REQUEST,&e)}}
#[cfg(test)] mod tests{
 use super::*;use axum::{body::to_bytes,http::Request as HttpRequest,routing::post,Router};use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};use tower::ServiceExt;
 #[test]fn rejects_remote_urls_untrusted_paths_and_invalid_uploads(){for s in ["https://127.0.0.1:3000","http://example.com:3000","http://127.0.0.2:3000","http://user@localhost:3000","http://localhost:3000/path","http://localhost:3000/?token=x","http://localhost:4319"]{assert!(endpoint(s).is_err(),"{s}")}assert!(endpoint("http://[::1]:3000").is_ok());assert!(remote_id("20261027-012345678-abcd"));assert!(!remote_id("../../elsewhere"));assert!(!safe_output("../../secret.png"));assert!(!safe_output("input-photo.png"));assert!(safe_output("out-01.png"));assert!(media_type(b"<html>not media</html>").is_none());}
 #[tokio::test]async fn guarded_local_transport_saves_receipts_and_never_repeats_after_restart(){
  let count=Arc::new(AtomicUsize::new(0));let calls=count.clone();let remote="20261027-012345678-abcd";
  let local=Router::new().route("/api/apps",axum::routing::get(||async{Json(json!({"apps":[{"id":"smoke","name":"Smoke","section":"utility","summary":"Example app","status":"ready","runnable":true,"inputs":[{"id":"style","type":"select","label":"Style","help":"Pick in order","multiple":{"max":2},"options":[{"value":"gold","label":"Gold","sets":[{"node":"1"}]}]}],"outputs":[{"type":"image","label":"Image"}],"presets":[{"id":"fast","label":"Fast"}],"models":[{"name":"model.safetensors","license":"MIT","gb":1,"gated":false,"repo":"untrusted-hidden"}],"credits":["Model author"],"example":{"url":"https://untrusted.invalid"}}]}))})).route("/api/apps/{app}/run",post(move|axum::extract::Path(app):axum::extract::Path<String>,body:axum::body::Bytes|{let calls=calls.clone();async move{calls.fetch_add(1,Ordering::SeqCst);assert!(body.windows(4).any(|w|w==b"test"));assert!(body.windows(14).any(|w|w==b"[\"gold\",\"red\"]"));if app=="uncertain"{(StatusCode::INTERNAL_SERVER_ERROR,Json(json!({"error":"not proof of non-execution"})))}else{(StatusCode::ACCEPTED,Json(json!({"id":remote,"status":"starting"})))}}})).route("/api/history/{id}",axum::routing::get(move||async move{Json(json!({"id":remote,"status":"succeeded","outputs":[{"file":"out-01.png","type":"image","url":"https://untrusted.invalid/steal"},{"file":"../../secret.png","type":"image"}]}))})).route("/api/history/{id}/files/{name}",axum::routing::get(||async{(StatusCode::OK,b"\x89PNG\r\n\x1a\nfixture".to_vec())})).route("/api/history/{id}/cancel",post(||async{Json(json!({"canceled":true}))}));
  let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let port=listener.local_addr().unwrap().port();let server=tokio::spawn(async move{axum::serve(listener,local).await.unwrap()});let tmp=tempfile::tempdir().unwrap();let make=||{let mut s=AppState::new("test".into(),Default::default());s.freefield=Arc::new(Hub::at(tmp.path().into()));Router::new().route("/discover",post(discover)).route("/submit",post(submit)).route("/receipt",post(receipt)).route("/poll",post(poll)).route("/download",post(download)).route("/cancel",post(cancel)).with_state(s)};let app=make();let base=format!("http://127.0.0.1:{port}");let request=|path:&str,v:Value|HttpRequest::builder().method("POST").uri(path).header("content-type","application/json").body(Body::from(v.to_string())).unwrap();let body=|r:Response|async move{serde_json::from_slice::<Value>(&to_bytes(r.into_body(),JSON_LIMIT).await.unwrap()).unwrap()};
  let catalog=app.clone().oneshot(request("/discover",json!({"serverUrl":base}))).await.unwrap();let catalog=body(catalog).await;assert_eq!(catalog["apps"][0]["id"],"smoke");assert_eq!(catalog["apps"][0]["outputs"][0]["type"],"image");assert_eq!(catalog["apps"][0]["inputs"][0]["multiple"]["max"],2);assert_eq!(catalog["apps"][0]["inputs"][0]["help"],"Pick in order");assert_eq!(catalog["apps"][0]["presets"][0]["id"],"fast");assert_eq!(catalog["apps"][0]["credits"][0],"Model author");assert!(!catalog.to_string().contains("untrusted"));assert!(catalog["apps"][0]["inputs"][0]["options"][0].get("sets").is_none());
  let id=uuid::Uuid::new_v4().to_string();let submit_request=|id:&str,app_id:&str|{let meta=json!({"serverUrl":base,"requestId":id,"appId":app_id,"approved":true,"preset":"fast","values":{"prompt":"test","style":["gold","red"]}}).to_string();let mut data=format!("--fixture\r\nContent-Disposition: form-data; name=\"metadata\"\r\n\r\n{meta}\r\n--fixture\r\nContent-Disposition: form-data; name=\"image\"; filename=\"image.png\"\r\nContent-Type: image/png\r\n\r\n").into_bytes();data.extend_from_slice(b"\x89PNG\r\n\x1a\ntest");data.extend_from_slice(b"\r\n--fixture--\r\n");HttpRequest::builder().method("POST").uri("/submit").header("content-type","multipart/form-data; boundary=fixture").body(Body::from(data)).unwrap()};let first=app.clone().oneshot(submit_request(&id,"smoke")).await.unwrap();assert_eq!(first.status(),StatusCode::OK);assert_eq!(body(first).await["remoteId"],remote);let repeated=make().oneshot(submit_request(&id,"smoke")).await.unwrap();assert_eq!(repeated.status(),StatusCode::BAD_REQUEST);assert_eq!(count.load(Ordering::SeqCst),1);let receipt=app.clone().oneshot(request("/receipt",json!({"serverUrl":base,"requestId":id}))).await.unwrap();assert_eq!(body(receipt).await["remoteId"],remote);
  let poll=app.clone().oneshot(request("/poll",json!({"serverUrl":base,"remoteId":remote}))).await.unwrap();let poll=body(poll).await;assert_eq!(poll["status"],"succeeded");assert_eq!(poll["outputs"].as_array().unwrap().len(),1);assert!(!poll.to_string().contains("untrusted"));let download=app.clone().oneshot(request("/download",json!({"serverUrl":base,"remoteId":remote,"index":0}))).await.unwrap();assert_eq!(download.status(),StatusCode::OK);assert_eq!(download.headers()[header::CONTENT_TYPE],"image/png");assert!(to_bytes(download.into_body(),100).await.unwrap().starts_with(b"\x89PNG"));let cancel=app.clone().oneshot(request("/cancel",json!({"serverUrl":base,"remoteId":remote,"approved":true}))).await.unwrap();assert_eq!(body(cancel).await["canceled"],true);
  let unknown=uuid::Uuid::new_v4().to_string();assert_eq!(app.clone().oneshot(submit_request(&unknown,"uncertain")).await.unwrap().status(),StatusCode::BAD_REQUEST);assert_eq!(make().oneshot(submit_request(&unknown,"uncertain")).await.unwrap().status(),StatusCode::BAD_REQUEST);let receipt=app.oneshot(request("/receipt",json!({"serverUrl":base,"requestId":unknown}))).await.unwrap();assert_eq!(body(receipt).await["status"],"unknown");assert_eq!(count.load(Ordering::SeqCst),2);server.abort();
 }
 #[tokio::test]async fn only_the_submit_route_accepts_a_reference_larger_than_four_mib(){
  use axum::extract::DefaultBodyLimit;
  let local=Router::new().route("/api/apps/smoke/run",post(|data:Bytes|async move{assert!(data.len()>4*1024*1024);(StatusCode::ACCEPTED,Json(json!({"id":"20261027-012345678-abcd"})))}).layer(DefaultBodyLimit::max(8*1024*1024)));
  let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let port=listener.local_addr().unwrap().port();let server=tokio::spawn(async move{axum::serve(listener,local).await.unwrap()});let tmp=tempfile::tempdir().unwrap();let mut state=AppState::new("fixture-token".into(),super::super::default_origins());state.freefield=Arc::new(Hub::at(tmp.path().into()));let app=super::super::router(state);let base=format!("http://127.0.0.1:{port}");let auth=|path:&str,ctype:&str,bytes:Vec<u8>|HttpRequest::builder().method("POST").uri(path).header("origin","http://localhost:5173").header("authorization","Bearer fixture-token").header("content-type",ctype).body(Body::from(bytes)).unwrap();
  let oversized=json!({"serverUrl":base,"junk":"x".repeat(5*1024*1024)}).to_string();let response=app.clone().oneshot(auth("/production/freefield/discover","application/json",oversized.into_bytes())).await.unwrap();assert_eq!(response.status(),StatusCode::PAYLOAD_TOO_LARGE);
  let meta=json!({"serverUrl":base,"requestId":uuid::Uuid::new_v4().to_string(),"appId":"smoke","approved":true}).to_string();let mut body=format!("--fixture\r\nContent-Disposition: form-data; name=\"metadata\"\r\n\r\n{meta}\r\n--fixture\r\nContent-Disposition: form-data; name=\"image\"; filename=\"image.png\"\r\nContent-Type: image/png\r\n\r\n").into_bytes();body.extend_from_slice(b"\x89PNG\r\n\x1a\n");body.extend(vec![0;5*1024*1024]);body.extend_from_slice(b"\r\n--fixture--\r\n");let response=app.oneshot(auth("/production/freefield/submit","multipart/form-data; boundary=fixture",body)).await.unwrap();assert_eq!(response.status(),StatusCode::OK);server.abort();
 }

}
